mapper.select:

where del_flag = '0'

    and station_id like concat('%', #{stationId}, '%')


    and station_name like concat('%', #{stationName}, '%')


    and dept_id = #{deptId}


    and enable_flag = #{enableFlag}


    and online_status = #{onlineStatus}

order by create_time desc

mapper.update:
update ieims_gnss_station
station_name = #{stationName}, longitude = #{longitude}, latitude = #{latitude}, altitude = #{altitude}, logo = #{logo}, dept_id = #{deptId}, manager = #{manager}, contact = #{contact}, phone = #{phone}, enable_flag = #{enableFlag}, online_status = #{onlineStatus}, last_online_time = #{lastOnlineTime}, remark = #{remark}, update_by = #{updateBy}, update_time = #{updateTime}
where id = #{id} and del_flag = '0'
